function [ys_, params, info] = steadystate(ys_, exo_, params)
% Steady state generated by Dynare preprocessor
    info = 0;
    params(17)=params(66)^params(3)/params(70)/params(18);
    params(88)=(1-params(13))*params(76)+params(13)*params(77);
    q_ss=params(78);
    tau_k_ss=params(25);
    tau_n_ss=params(24);
    tau_c_ss=params(23);
    rK_ss=(q_ss*(params(66)^params(3)/params(17)-1+params(6))-tau_k_ss*params(6))/(1-tau_k_ss);
    pH_ss=params(78)*(1/(1-params(8))*(1-params(8)*(1/params(78))^(1-params(7))))^(1/(1-params(7)));
    params(80)=params(79)*(1-(1-params(6))/params(66))/(1-(1-params(20))/params(66));
    yH_ss=(params(65)*(pH_ss*params(80)*params(5)/rK_ss)^params(15)*(pH_ss*params(5)/rK_ss)^params(5)*(params(66)*params(88))^(1-params(5)-params(15)))^(1/(1-params(5)-params(15)));
    k_ss=params(66)*pH_ss*params(5)*yH_ss/rK_ss;
    k_g_ss=params(80)*k_ss;
    g_i_ss=(1-(1-params(20))/params(66))*k_g_ss;
    k_o_ss=k_ss/(1-params(13));
    i_o_ss=(1-(1-params(6))/params(66))*k_o_ss;
    i_ss=(1-params(13))*i_o_ss;
    w_ss=yH_ss*pH_ss*(1-params(5)-params(15))/params(88);
    params(84)=pH_ss*yH_ss/(1-params(72));
    params(68)=params(72)*params(84)/params(69);
    g_c_ss=params(84)*params(73)/params(78);
    params(26)=g_i_ss;
    params(29)=g_c_ss;
    params(85)=params(84)*params(81);
    params(86)=params(84)*params(82);
    f_star_o_ss=params(86)/(1-params(13));
    params(87)=params(68)*params(69)*(1-params(9))-(1-params(70)*params(18)/params(66))*(params(85)+params(86));
    params(83)=(params(85)+params(86))/params(84);
    c_ss=(params(84)-params(87))/params(78)-i_ss-g_c_ss-g_i_ss;
    yC_ss=g_i_ss+g_c_ss+i_ss+c_ss;
    xF_ss=yC_ss*params(8)*(1/params(78))^(-params(7));
    xH_ss=yC_ss*(1-params(8))*(pH_ss/params(78))^(-params(7));
    yF_ss=xF_ss;
    xHstar_ss=(yF_ss+params(87)-params(69)*params(68))/pH_ss;
    params(22)=xHstar_ss/(pH_ss^(-params(14))*params(71));
    pi_ss=yH_ss*pH_ss*params(15);
    tr_ss=params(84)*params(74);
    params(75)=(-(params(85)+params(68)*params(69)*params(9)+params(76)*(1-params(13))*tau_n_ss*w_ss+k_ss*tau_k_ss*(rK_ss-params(6))/params(66)+c_ss*params(78)*tau_c_ss-params(78)*g_c_ss-params(78)*g_i_ss-params(85)*params(70)*params(18)/params(66)-tr_ss))/(1-params(13));
    params(32)=tr_ss;
    tr_o_ss=tr_ss*(1-params(19))/(1-params(13));
    tr_r_ss=tr_ss*params(19)/params(13);
    c_r_ss=(tr_r_ss+params(77)*w_ss)/(params(78)*(1+tau_c_ss));
    c_o_ss=(c_ss-params(13)*c_r_ss)/(1-params(13));
    c_hat_o_ss=((1-params(12))^(1/params(11))*(c_o_ss-c_o_ss*params(1)/params(66))^((params(11)-1)/params(11))+params(12)^(1/params(11))*g_c_ss^((params(11)-1)/params(11)))^(params(11)/(params(11)-1));
    c_hat_r_ss=(params(12)^(1/params(11))*g_c_ss^((params(11)-1)/params(11))+(1-params(12))^(1/params(11))*(c_r_ss-c_r_ss*params(1)/params(66))^((params(11)-1)/params(11)))^(params(11)/(params(11)-1));
    chitil_o_ss=c_hat_o_ss^params(3);
    chitil_r_ss=c_hat_r_ss^params(3);
    Theta_o_ss=1;
    Theta_r_ss=1;
    lam_o_ss=c_hat_o_ss^(-params(3))/(params(78)*(1+tau_c_ss))*((1-params(12))*c_hat_o_ss/(c_o_ss-c_o_ss*params(1)/params(66)))^(1/params(11));
    lam_r_ss=c_hat_r_ss^(-params(3))/(params(78)*(1+tau_c_ss))*((1-params(12))*c_hat_r_ss/(c_r_ss-c_r_ss*params(1)/params(66)))^(1/params(11));
    params(62)=w_ss*lam_o_ss*(1-tau_n_ss)/params(76)^params(4);
    params(63)=w_ss*lam_r_ss/params(77)^params(4);
    gdp_nco_ss=pH_ss*yH_ss/params(78);
    ys_(1)=lam_o_ss;
    ys_(2)=c_hat_o_ss;
    ys_(3)=c_o_ss;
    ys_(4)=params(76);
    ys_(5)=i_o_ss;
    ys_(6)=k_o_ss;
    ys_(7)=f_star_o_ss;
    ys_(8)=Theta_o_ss;
    ys_(9)=chitil_o_ss;
    ys_(10)=lam_r_ss;
    ys_(11)=c_hat_r_ss;
    ys_(12)=c_r_ss;
    ys_(13)=params(77);
    ys_(14)=Theta_r_ss;
    ys_(15)=chitil_r_ss;
    ys_(16)=c_ss;
    ys_(17)=params(88);
    ys_(18)=i_ss;
    ys_(19)=k_ss;
    ys_(20)=params(86);
    ys_(21)=q_ss;
    ys_(22)=w_ss;
    ys_(23)=rK_ss;
    ys_(24)=params(84);
    ys_(25)=yC_ss;
    ys_(26)=yF_ss;
    ys_(27)=yH_ss;
    ys_(28)=xF_ss;
    ys_(29)=xH_ss;
    ys_(30)=xHstar_ss;
    ys_(31)=pi_ss;
    ys_(32)=pH_ss;
    ys_(33)=params(78);
    ys_(34)=params(87);
    ys_(35)=params(18);
    ys_(45)=params(85);
    ys_(36)=tau_k_ss;
    ys_(37)=tau_n_ss;
    ys_(38)=tau_c_ss;
    params(25)=tau_k_ss;
    params(24)=tau_n_ss;
    params(23)=tau_c_ss;
    ys_(39)=k_g_ss;
    ys_(40)=g_c_ss;
    ys_(41)=g_i_ss;
    ys_(42)=tr_ss;
    ys_(43)=tr_o_ss;
    ys_(44)=tr_r_ss;
    ys_(46)=gdp_nco_ss;
    ys_(47)=params(61);
    ys_(48)=params(62);
    ys_(49)=params(63);
    ys_(50)=params(64);
    ys_(51)=params(65);
    ys_(52)=params(66);
    ys_(53)=params(67);
    ys_(56)=params(70);
    ys_(55)=params(69);
    ys_(54)=params(68);
    ys_(57)=params(71);
    ys_(58)=params(84)-params(69)*params(68);
    ys_(59)=params(66);
    ys_(60)=params(66)^4;
    ys_(61)=params(66);
    ys_(62)=params(66);
    ys_(63)=params(66);
    gam_YCo=params(66);
    gam_Ystar=params(66);
    gam_pCostar=1;
    ys_(64)=params(66);
    ys_(65)=params(85)*(1-1/params(66))/params(84);
    ys_(69)=params(86)*(1-1/params(66))/params(84);
    ys_(67)=1/params(78);
    ys_(66)=params(87)/params(84);
    ys_(68)=params(66);
    ys_(70)=0;
    ys_(71)=0;
    ys_(72)=0;
    ys_(73)=0;
    ys_(74)=0;
    ys_(75)=0;
    ys_(76)=0;
    ys_(77)=0;
    ys_(80)=0;
    ys_(82)=0;
    ys_(78)=0;
    ys_(79)=0;
    ys_(81)=0;
    ys_(83)=0;
    % Auxiliary equations
ys_(84)=ys_(58);
ys_(85)=ys_(58);
ys_(86)=ys_(58);
ys_(87)=ys_(52);
ys_(88)=ys_(52);
ys_(89)=ys_(52);
end
